import Foundation

/// One entry of `chess_puzzles.json` (generated by Scripts/build_chess_puzzles.py).
public struct ChessPuzzle: Codable, Hashable, Sendable, Identifiable {
    public let id: String
    /// Position BEFORE the opponent's move.
    public let fen: String
    /// The opponent's move (UCI) that leads to the position shown to the player.
    public let opponentFirstMove: String
    /// Player move, opponent reply, player move, … (UCI). Always ends with the player's mating move.
    public let solution: [String]
    public let rating: Int
    public let mateIn: Int
    public let difficulty: Difficulty

    public init(id: String, fen: String, opponentFirstMove: String, solution: [String], rating: Int, mateIn: Int, difficulty: Difficulty) {
        self.id = id; self.fen = fen; self.opponentFirstMove = opponentFirstMove
        self.solution = solution; self.rating = rating; self.mateIn = mateIn; self.difficulty = difficulty
    }

    /// Position after the opponent's first move (what the player sees).
    public func startPosition() throws -> Position {
        let p = try Position(fen: fen)
        guard let m = Move(uci: opponentFirstMove) else { throw ChessError.illegalMove(opponentFirstMove) }
        return try p.applying(m)
    }
}

public final class ChessPuzzleBank: @unchecked Sendable {
    public let puzzles: [ChessPuzzle]

    public init(puzzles: [ChessPuzzle]) { self.puzzles = puzzles }

    public convenience init?(data: Data) {
        guard let list = try? JSONDecoder().decode([ChessPuzzle].self, from: data) else { return nil }
        self.init(puzzles: list)
    }

    public static func load(from bundle: Bundle) -> ChessPuzzleBank? {
        guard let url = bundle.url(forResource: "chess_puzzles", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return ChessPuzzleBank(data: data)
    }

    public func puzzles(for difficulty: Difficulty) -> [ChessPuzzle] {
        let d: Difficulty = difficulty == .quick ? .easy : difficulty
        return puzzles.filter { $0.difficulty == d }
    }

    /// The first easy mate-in-one (used by onboarding).
    public var firstEasyMateInOne: ChessPuzzle? {
        puzzles.first { $0.difficulty == .easy && $0.mateIn == 1 }
    }

    /// Fallback used if the JSON is missing: a classic back-rank mate.
    public static let fallback = ChessPuzzle(
        id: "fallback",
        fen: "6k1/5ppp/8/8/8/8/1q3PPP/3R2K1 b - - 0 1",
        opponentFirstMove: "b2a2",
        solution: ["d1d8"],
        rating: 600, mateIn: 1, difficulty: .easy)
}

public enum ChessMoveOutcome: Equatable, Sendable {
    /// Correct move; the round continues with an opponent reply to auto-play.
    case correctContinue(san: String)
    /// Correct final move: checkmate.
    case solved(san: String)
    /// Wrong move (snaps back). `triesLeft` remaining.
    case wrong(triesLeft: Int)
    /// Third miss: round failed.
    case failed
    case illegal
}

public struct ChessRound: PuzzleRound, Equatable {
    public var game: GameID { .chess }
    public let difficulty: Difficulty
    public let puzzle: ChessPuzzle
    public static let maxMisses = 3

    public private(set) var position: Position
    /// Index into `puzzle.solution` of the next expected move.
    public private(set) var step: Int = 0
    public private(set) var misses: Int = 0
    public private(set) var status: RoundStatus = .playing
    public private(set) var lastMove: Move?
    public private(set) var finalSAN: String?
    /// The colour the player plays (board orientation).
    public let playerColor: PieceColor

    public init(puzzle: ChessPuzzle, difficulty: Difficulty) throws {
        self.puzzle = puzzle
        self.difficulty = difficulty
        let start = try puzzle.startPosition()
        self.position = start
        self.playerColor = start.sideToMove
        self.lastMove = Move(uci: puzzle.opponentFirstMove)
    }

    /// Position before the opponent's first move (for the opening animation).
    public var initialPosition: Position? { try? Position(fen: puzzle.fen) }

    public var headerText: String {
        let side = playerColor == .white ? "White" : "Black"
        let n = puzzle.mateIn == 1 ? "one" : puzzle.mateIn == 2 ? "two" : "\(puzzle.mateIn)"
        return "\(side) to move. Mate in \(n)."
    }

    public var isPlayersTurn: Bool { status == .playing && position.sideToMove == playerColor }

    public var expectedMove: Move? {
        step < puzzle.solution.count ? Move(uci: puzzle.solution[step]) : nil
    }

    /// The opponent reply waiting to be played, if any.
    public var pendingOpponentReply: Move? {
        guard status == .playing, position.sideToMove != playerColor, step < puzzle.solution.count else { return nil }
        return Move(uci: puzzle.solution[step])
    }

    private var isFinalPlayerMove: Bool { step == puzzle.solution.count - 1 }

    public mutating func play(_ move: Move) -> ChessMoveOutcome {
        guard isPlayersTurn else { return .illegal }
        // Auto-queen if the UI didn't ask (the UI shows a picker, but be safe).
        var move = move
        if move.promotion == nil, position[move.from]?.kind == .pawn,
           Square.rank(move.to) == (playerColor == .white ? 7 : 0) {
            move = Move(from: move.from, to: move.to, promotion: .queen)
        }
        guard position.isLegal(move) else { return .illegal }
        let san = position.san(move)
        let next = position.applying(unchecked: move)
        let matches = move == expectedMove
        let altMate = isFinalPlayerMove && next.isCheckmate
        if matches || altMate {
            position = next
            lastMove = move
            step += 1
            if isFinalMoveDone(next) {
                status = .solved
                finalSAN = san
                return .solved(san: san)
            }
            return .correctContinue(san: san)
        }
        misses += 1
        if misses >= Self.maxMisses {
            status = .failed
            return .failed
        }
        return .wrong(triesLeft: Self.maxMisses - misses)
    }

    private func isFinalMoveDone(_ next: Position) -> Bool {
        step >= puzzle.solution.count || next.isCheckmate
    }

    /// Plays the opponent's scripted reply.
    @discardableResult
    public mutating func playOpponentReply() -> Move? {
        guard let reply = pendingOpponentReply, position.isLegal(reply) else { return nil }
        position = position.applying(unchecked: reply)
        lastMove = reply
        step += 1
        return reply
    }

    /// The full solution line from the current point (used to animate the answer after failing).
    public static func solutionLine(for puzzle: ChessPuzzle) -> [Move] {
        puzzle.solution.compactMap(Move.init(uci:))
    }
}

public struct ChessGame: PuzzleGame {
    public let id: GameID = .chess
    public let bank: ChessPuzzleBank

    public init(bank: ChessPuzzleBank) { self.bank = bank }

    public func makeRound(difficulty: Difficulty) async -> any PuzzleRound {
        let pool = bank.puzzles(for: difficulty)
        for _ in 0..<10 {
            if let p = pool.randomElement(), let round = try? ChessRound(puzzle: p, difficulty: difficulty) { return round }
        }
        // swiftlint:disable:next force_try
        return try! ChessRound(puzzle: ChessPuzzleBank.fallback, difficulty: difficulty)
    }
}
